after.scss:
@use "gerillass" as *;

.element{
  @include after{
    content: "Easy to use!";
    font-style: italic;
    color: red;
  };
}

all-buttons.scss:
@use "gerillass" as *;

@include all-buttons {
  background-color: teal;
  color: white;
}
@include all-buttons(hover) {
  background-color: teal;
  color: white;
}
@include all-buttons(focus) {
  background-color: purple;
  color: white;
}
@include all-buttons(active) {
  background-color: blue;
  color: white;
}
@include all-buttons(disabled) {
  background-color: gray;
  color: black;
}

all-text-inputs.scss:
@use "gerillass" as *;

.element {
  @include all-text-inputs(required) {
    background-color: orange;
    color: white;
  };
}

aspect-ratio.scss:
@use "gerillass" as *;

.video iframe {
  @include aspect-ratio("16/9");
}

.avatar {
  @include aspect-ratio("1:1", contain);
}

.panel {
  @include aspect-ratio(1.5, null);
}

before.scss:
@use "gerillass" as *;

.element{
  @include before{
    content: "Easy to use!";
    font-style: italic;
    color: red;
  };
}

breakpoint.scss:
@use "gerillass" as *;

.header{
  @include breakpoint(min, large) {
    padding: 2rem 4rem;
  };
}

.card{
  @include breakpoint(between, small large) {
    flex: 0 0 50%;
  };
}

.sidebar{
  @include breakpoint(max, medium) {
    display: none;
  };
}

.footer{
  @include breakpoint(only, 1200px) {
    text-align: center;
  };
}

breakpointer.scss:
@use "gerillass" as *;

@include breakpointer {
  position: fixed;
  top: 0;
  right: 0;
  color: white;
  padding: 5px 10px;
  z-index: 10;
}

center.scss:
@use "gerillass" as *;

.parent-element {
  position: relative;
  .element{
    position: absolute;
    @include center(horizontal);
  }
}

columnizer.scss:
@use "gerillass" as *;

.parent-element{
  @include columnizer(2, 10px, true);
  @include breakpoint(min, large) {
    @include columnizer(4, 20px, false);
  }
}

container-query.scss:
@use "gerillass" as *;

.card {
  @include container("card");
}

// The query goes on a descendant of the container, never on the
// container itself. Nothing warns you when it is on the wrong element.
.card .title {
  @include container-query("min", 400px) {
    font-size: 2rem;
  }
}

counter.scss:
@use "gerillass" as *;

.listicle-wrapper {
  @include counter {
    position: absolute;
    top: 0;
    left: 0;
    font-size: 7em;
    font-weight: bold;
    font-style: italic;
    font-family: "Jumble", sans-serif;
    transform: translateY(-20%);
    color: rgb(230,230,230);
    line-height: 1;
    z-index: -1;
  };
  .item {
    position: relative;
    padding-left: 50px;
    &:not(:last-child) {
        margin-bottom: 3rem;
    }
  }
}

escape-to-parent.scss:
@use "gerillass" as *;

.parent-element{
  .element{
    @include escape-to-parent(".smartphone"){
      background-color: red;
    }
    @include escape-to-parent(".desktop"){
      background-color: green;
    }
  }
}

font-face.scss:
@use "gerillass" as *;

@include font-face (
  $font-weight: 700,
  $font-style: italic,
  $file-formats: eot woff2 woff, 
  $font-family: "Fanwood Text",
  $file-path: "fonts/fanwood-text/fanwood-text-bold-italic",
);

loadify.scss:
@use "gerillass" as *;

@include loadify(init);

.parent-element {
  .item {
    @include only(1) {
      @include loadify(0.2s, 0.6s);
    }
    @include only(2) {
      @include loadify(0.4s, 0.6s);
    }
    @include only(3) {
      @include loadify(0.6s, 0.6s);
    }
  }
}

only.scss:
@use "gerillass" as *;

.cards {
  .card {
    @include only(2) {
      background-color: #5bc0bb;
    }
  }
}

.articles {
  article {
    @include only(-1) {
      border-bottom: 0;
    }
  }
}

.gallery {
  figure {
    @include only(1, -1) {
      grid-column: span 2;
    }
  }
}

scissors.scss:
@use "gerillass" as *;

.element{
  height: 200px;
  display: flex;
  justify-content: center;
  background-color: #5bc0bb;
  @include scissors(0 0 50% 50%);
  h2 {
    color: white;
    font-size: 2.5em; 
    text-align: center;
  }
}

sprite.scss:
@use "gerillass" as *;

.sprite-element{
  @include sprite("sprite.png") {
    width: 100px;
    height: 100px;
  };
  &.first {
    @include sprite(0 0);
  }
  &.second {
    @include sprite(-100px 0)
  }
  &.third {
    @include sprite(-200px 0)
  }
  &.fourth {
    @include sprite(-300px 0)
  }
}

text-selection.scss:
@use "gerillass" as *;

.element{
  @include text-selection(only){
    color: pink;
    background-color: red;
  }
}

text-shadow.scss:
@use "gerillass" as *;

.element{
  transition: .3s;
  @include text-shadow(left gold 3px true);
  &:hover{
    @include text-shadow(right gold 8px true);
  }
  &:active{
    @include text-shadow(right deepskyblue 8px true);
  }
}

triangle.scss:
@use "gerillass" as *;

.element{
  &::after {
    @include triangle(
      $direction: "bottom",
      $color: crimson,
      $size: 10px 6px
    ) {
      position: relative;
      margin-left: 6px;
      top: -2px;
    };
  }
}
